import dspy
from litellm.utils import Choices, Message, ModelResponse

class CorpClient:
    def __init__(self):
        self.calls = []
    def create(self, *, messages, **kwargs):
        self.calls.append({'messages': messages, 'kwargs': kwargs})
        return ModelResponse(
            choices=[Choices(message=Message(content='[[ ## answer ## ]]\nblue'))],
            model='corp/internal-chat',
            usage={'prompt_tokens': 1, 'completion_tokens': 1, 'total_tokens': 2},
        )

class CorpLM(dspy.BaseLM):
    def __init__(self, client):
        super().__init__(model='corp/internal-chat', model_type='chat', temperature=0.0, max_tokens=128, cache=False)
        self.client = client
    @property
    def supports_function_calling(self):
        return False
    @property
    def supports_reasoning(self):
        return False
    @property
    def supports_response_schema(self):
        return False
    @property
    def supported_params(self):
        return set()
    def forward(self, prompt=None, messages=None, **kwargs):
        return self.client.create(messages=messages or [{'role': 'user', 'content': prompt}], **{**self.kwargs, **kwargs})
    async def aforward(self, prompt=None, messages=None, **kwargs):
        return self.forward(prompt=prompt, messages=messages, **kwargs)

client = CorpClient()
dspy.configure(lm=CorpLM(client))
qa = dspy.Predict('question -> answer')
result = qa(question='What color is the sky?')

captured = client.calls[0]
assert result.answer == 'blue'
assert captured['messages'][0]['role'] == 'system'
assert captured['messages'][1]['role'] == 'user'
print('answer', result.answer)
print('captured_roles', [m['role'] for m in captured['messages']])
